import{_ as p,a as i}from"./chunks/cg-xjlb3.2d4b72fa.js";import{_ as t}from"./chunks/cg-mblb5.2274d1a8.js";import{_ as o,o as a,c as u,O as e}from"./chunks/framework.ac0f74f3.js";const r="/assets/cg-mblb1.350dde6a.png",q="/assets/cg-mblb2.2c569d44.png",s="/assets/cg-mblb4.e41ab31c.png",x=JSON.parse('{"title":"模板列表-采购","description":"","frontmatter":{},"headers":[],"relativePath":"采购管理/模板列表.md","filePath":"采购管理/模板列表.md"}'),c={name:"采购管理/模板列表.md"};function n(_,l,m,d,h,b){return a(),u("div",null,[...l[0]||(l[0]=[e('<h1 id="模板列表-采购" tabindex="-1">模板列表-采购 <a class="header-anchor" href="#模板列表-采购" aria-label="Permalink to &quot;模板列表-采购&quot;">​</a></h1><blockquote><p>&quot;模板列表&quot;位于采购管理板块，在&quot;模板列表&quot;中可以维护个人的 &quot;采购合同模板&quot; &quot;采购询价模板&quot;</p></blockquote><h4 id="_1-新增模板" tabindex="-1">1. 新增模板 <a class="header-anchor" href="#_1-新增模板" aria-label="Permalink to &quot;1. 新增模板&quot;">​</a></h4><ul><li>输入模板的名称,选择模板的类型，分为两种:采购询价以及采购合同</li><li>填写排序值(排序值是指输入的数字越大,显示和选择时就越靠前）</li><li>模板状态分为：可用(编辑完提交后) ,草稿(编辑完没有提交而是保存草稿)</li><li>草稿转可用状态：点击草稿后面的 &quot;详情&quot; 进行提交就转换为 &quot;可用&quot; 状态</li><li>删除：支持删除模板，删除时系统会提示是否确认删除</li></ul><p><img src="'+r+'" alt="如图所示"></p><h4 id="_2-新增采购询价单模板" tabindex="-1">2.新增采购询价单模板 <a class="header-anchor" href="#_2-新增采购询价单模板" aria-label="Permalink to &quot;2.新增采购询价单模板&quot;">​</a></h4><blockquote><p>在模板列表中新增询价单，可以选择供方名称，供方联系人，报价类型，支持修改需方，供方信息，鼠标悬浮在表字段可添加新的&quot;字段&quot;(双击编辑字段名称),新加字段支持&quot;删除&quot; &quot;添加&quot; ，拖动下方滚动条可查看更多信息、可添加备注</p></blockquote><ul><li><p>供方信息：来源于采购管理,供应商列表中添加的客户信息</p></li><li><p>供方联系人：来源于供应商列表中添加了的联系人(可添加多个联系人)</p></li><li><p>类型：来源于财务管理，汇率税率列表中添加的汇率税率信息</p></li><li><p>小眼睛图标：指页面中需方/供方列表中的小眼睛图标，默认全展示，可关闭或打开（根据模板创建的询价，双方信息中不显示的部分，直接不显示）</p></li><li><p>小笔图标：文字傍边带有小笔图标的方可编辑</p></li></ul><p><img src="'+q+'" alt="如图所示"></p><h4 id="_3-根据询价模板生成询价单" tabindex="-1">3. 根据询价模板生成询价单 <a class="header-anchor" href="#_3-根据询价模板生成询价单" aria-label="Permalink to &quot;3. 根据询价模板生成询价单&quot;">​</a></h4><blockquote><p>创建的询价单模板可生成询价单转到采购管理,&quot;询价列表中&quot;,可下载/打印</p></blockquote><ul><li><p>供方信息：来源于采购管理,供应商列表中添加的客户信息</p></li><li><p>关联公司：供方/需方可通过下拉框选择关联公司，同时会根据选择的关联公司，进行信息的更换</p><p>-使用关联公司时，签章时所用的印章为关联公司印章。（关联公司印章也需要设置后对人员进行授权）</p></li><li><p>供方联系人 : 来源于供应商列表中添加的联系人(可添加多个联系人)</p></li><li><p>类型 : 来源于财务管理,汇率税率列表中添加的汇率税率信息</p></li><li><p>选择产品 : 产品来源于所添加供应商公司产品列表中的产品（可输入产品点击&quot;对号&quot;图标创建产品字段）</p><p>-可在需方/供方之间切换选择产品</p></li><li><p>点击选择按钮可在弹窗中批量选择产品进行录入</p></li><li><p>点击打印设置按钮可设定打印宽度</p></li><li><p>批量导入：可批量导入产品（先下载模板Excel进行编辑导入即可）</p></li><li><p>编辑名称:点击编辑名称按钮可对询价单的名称进行编辑</p></li><li><p>小眼睛图标：指的是页面中需方/供方列表中的小眼睛图标，默认全展示，可选择关闭或者打开（如果关闭对方将无法看到这条信息，包括打印和下载都不展示）</p></li><li><p>小笔图标：文字傍边带有小笔图标的方可编辑</p></li><li><p>下载图标：点击下载图标可下载当前页面内容</p></li><li><p>打印图标：点击可打印当前页面的信息</p></li><li><p>使用提示：点击使用提示可弹出弹窗，在弹窗中显示动图，可切换查看对应功能的使用（新增字段，批量修改价格，调整宽度，签章显示，签章不显示）</p></li></ul><p><img src="'+p+'" alt="如图所示"></p><ul><li><p>货期：点击选择货期时间，支持一键录入货期</p></li><li><p>内部型号：点击选择内部型号（选择自己公司对应的产品，物料）</p><p>-悬浮显示产品的编号型号</p></li><li><p>历史报价 : 跟同个公司询价过同个产品时，如果再次询价就会显示之前的产品历史报价信息</p></li><li><p>历史成交价 : 跟同个公司成交过这个产品，成功以后再次询价时会显示之前的产品历史成交价</p></li><li><p>单价/总计小数点位数显示：根据汇率税率列表中设置的小数位数显示小数位数</p><p>-（例如：设置的小数位数是2位，产品列表中单价，总价显示的金额位数是两位）</p></li><li><p>总计 : 是所添加的产品单价的总计(支持更改单价添加公式(加 , 减 , 乘(乘的是百分比，1就是0.01) 输入数值)</p></li><li><p>字段更改 : 在添加产品信息以后可以悬浮对应的产品信息如果出现&quot;更改的小笔图标&quot;就代表可以更改这个产品的信息内容,或者双击也可以更改</p></li><li><p>产品查询：支持查询已添加的产品信息</p></li><li><p>备注：可输入询价信息的备注</p></li><li><p>存为模板 : 如果点击存为模板在模板列表中显示所存的模板</p></li><li><p>确认:如果点击确认,询价单将发送给供方，询价列表显示状态&quot;未报价&quot;</p></li><li><p>保存草稿 : 点击保存草稿,在询价列表显示状态为 &quot;草稿&quot;</p></li></ul><p><img src="'+i+'" alt="如图所示"></p><h4 id="_4-新增采购合同单模板" tabindex="-1">4.新增采购合同单模板 <a class="header-anchor" href="#_4-新增采购合同单模板" aria-label="Permalink to &quot;4.新增采购合同单模板&quot;">​</a></h4><blockquote><p>在模板列表中新增合同单，可以选择乙方信息，乙方联系人，语言，类型，支持修改甲方，乙方信息，鼠标悬浮在表字段可以添加新的&quot;字段&quot;(双击编辑字段名称),新加字段支持&quot;删除&quot;,&quot;添加&quot;， 表格标题右侧可拖动调整列宽，拖动下方滚动条可查看更多信息，可添加条款内容，选择抄送对象，可在表格字段中或者表格字段下方添加货期</p></blockquote><ul><li><p>乙方信息：来源于采购管理,供应商列表中添加的客户信息</p></li><li><p>乙方联系人：来源于供应商列表中添加了的联系人(可添加多个联系人)</p></li><li><p>类型：来源于财务管理，汇率税率列表中添加的汇率税率信息</p></li><li><p>语言：可选中文和英文</p></li><li><p>小眼睛图标：指页面中甲方/乙方列表中的小眼睛图标，默认全展示，可关闭或打开（根据模板创建的询价，双方信息中不显示的部分，直接不显示）</p></li><li><p>小笔图标：文字傍边带有小笔图标的方可编辑</p></li><li><p>点击打印设置按钮可设定打印宽度</p></li><li><p>使用提示：点击使用提示可弹出弹窗，在弹窗中显示动图，可切换查看对应功能的使用（新增字段，批量修改价格，调整宽度，签章显示，签章不显示）</p></li><li><p>编辑名称:点击编辑名称按钮可对询价单的名称进行编辑</p></li></ul><p><img src="'+s+'" alt="如图所示"></p><h4 id="_5-根据采购合同模板生成合同单" tabindex="-1">5.根据采购合同模板生成合同单 <a class="header-anchor" href="#_5-根据采购合同模板生成合同单" aria-label="Permalink to &quot;5.根据采购合同模板生成合同单&quot;">​</a></h4><blockquote><p>创建的合同模板可直接生成合同单转到采购管理,&quot;合同列表中&quot;,可下载/打印</p></blockquote><ul><li><p>乙方信息：来源于采购管理,供应商列表中添加的客户信息</p></li><li><p>关联公司：供方/需方可通过下拉框选择关联公司，同时会根据选择的关联公司，进行信息的更换</p><p>-使用关联公司时，签章时所用的印章为关联公司印章。（关联公司印章也需要设置后对人员进行授权）</p></li><li><p>乙方联系人 : 来源于供应商列表中添加的联系人(可添加多个联系人)</p></li><li><p>语言:可选择中文/英文</p></li><li><p>类型 : 来源于财务管理,汇率税率列表中添加的汇率税率信息</p></li><li><p>选择产品 : 产品来源于所添加甲方公司产品列表中的产品（可输入产品点击&quot;对号&quot;图标创建产品字段）</p><p>-可切换选择录入甲方/乙方产品</p></li><li><p>点击选择按钮可在弹窗中批量选择产品进行录入</p></li><li><p>批量导入：可批量导入产品（先下载模板Excel进行编辑导入即可）</p></li><li><p>产品查询：支持查询已添加的产品信息</p></li><li><p>批量删除：勾选序号前的勾选框方可批量删除已添加的产品，或点击删除图标单独删除</p></li><li><p>小眼睛图标：指的是页面中需方/供方列表中的小眼睛图标，默认全展示，可选择关闭或者打开（如果关闭对方将无法看到这条信息，包括打印和下载都不展示）</p></li><li><p>小笔图标：文字傍边带有小笔图标的方可编辑</p></li><li><p>下载图标：点击下载图标可下载当前页面内容</p></li><li><p>打印图标：点击可打印当前页面的信息</p></li><li><p>点击打印设置按钮可设定打印宽度</p></li><li><p>更改记录：点击更改记录按钮可查看更改详情</p></li><li><p>编辑名称:点击编辑名称按钮可对合同单的名称进行编辑</p></li><li><p>使用提示：点击使用提示可弹出弹窗，在弹窗中显示动图，可切换查看对应功能的使用（新增字段，批量修改价格，调整宽度，签章显示，签章不显示）</p></li><li><p>货期：点击选择货期时间，支持一键录入货期</p></li><li><p>内部型号：点击选择内部型号（选择自己公司对应的产品，物料）</p><p>-悬浮显示产品的编号型号</p></li><li><p>历史报价 : 跟同个公司询价过同个产品时，如果再次询价就会显示之前的产品历史报价信息</p></li><li><p>历史成交价 : 跟同个公司成交过这个产品，成功以后再次询价时会显示之前的产品历史成交价</p></li><li><p>单价/总计小数点位数显示：根据汇率税率列表中设置的小数位数显示小数位数</p><p>-（例如：设置的小数位数是2位，产品列表中单价，总价显示的金额位数是两位）</p></li><li><p>总计 : 是所添加的产品单价的总计(支持更改单价添加公式(加 , 减 , 乘(乘的是百分比，1就是0.01) 输入数值)</p></li><li><p>字段更改 : 在添加产品信息以后可以悬浮对应的产品信息如果出现&quot;更改的小笔图标&quot;就代表可以更改这个产品的信息内容,或者双击也可以更改</p></li><li><p>合同附件：点击可上传合同附件，支持删除/下载</p></li><li><p>抄送：下方文本框内所填写的信息会发送给所勾选的抄送对象</p><p>-文本框所编辑的条款需要使用时记得勾选条款前面的勾选框才能显示出来</p></li><li><p>存为模板 : 如果点击存为模板在模板列表中显示所存的模板</p></li><li><p>签章：如果点击签章在选择合同章确认以后,在合同列表显示，（签章之前需填写货期）</p></li><li><p>保存：点击保存,在合同列表显示状态为 &quot;未签章&quot;，点击详情可进去签章</p><p>-编辑合同信息的时候，可以将合同暂存下来， 状态是未签章</p></li></ul><p><img src="'+t+'" alt="如图所示"></p>',23)])])}const P=o(c,[["render",n]]);export{x as __pageData,P as default};
